create table svcs_directory (
    service_id                  number
        generated by default on null as identity
    not null enable,
    fk_nursing_unit_id          number,
    patient_type                varchar2(4000 char),
    patient_type_alias          varchar2(4000 char),
    medical_service             varchar2(4000 char),
    op_prefix                   varchar2(4000 char),
    aff_srvc_pool_alias         varchar2(4000 char),
    med_svc_alias               varchar2(4000 char),
    patient_service_code        varchar2(4000 char),
    patient_service_description varchar2(4000 char),
    status                      varchar2(4000 char),
    added_dt                    varchar2(4000 char),
    inactive_dt                 varchar2(4000 char)
);

alter table svcs_directory
    add constraint nurse_unit_disp_id_pk primary key ( service_id )
        using index enable;


